css:
.pe-root {
  --pe-panel-width: 320px;
  --pe-ink: #302e26;
  --pe-muted: #756e60;
  --pe-paper: #fffdf8;
  --pe-line: #e4dfd3;
  --pe-accent: #687644;
  --pe-accent-dark: #47542c;
  --pe-soft: #f2efe5;
  font-family: Arial, Helvetica, sans-serif;
  color: var(--pe-ink);
  font-size: 14px;
  line-height: 1.45;
  text-align: left;
  direction: ltr;
}

.pe-root *, .pe-root *::before, .pe-root *::after { box-sizing: border-box; }
.pe-root [hidden] { display: none !important; }
.pe-root button, .pe-root input, .pe-root textarea, .pe-root select { font: inherit; }
.pe-root button { cursor: pointer; }
.pe-root button:disabled { cursor: not-allowed; opacity: .42; }
.pe-root button:focus-visible, .pe-root input:focus-visible,
.pe-root textarea:focus-visible, .pe-root select:focus-visible {
  outline: 3px solid #b36b2d;
  outline-offset: 3px;
}
.pe-root p, .pe-root h2, .pe-root h3 { margin: 0; }
.pe-root button { text-transform: none; letter-spacing: normal; }

.pe-launcher {
  position: fixed;
  z-index: 100010;
  top: max(14px, env(safe-area-inset-top));
  right: max(18px, env(safe-area-inset-right));
  padding: 10px 17px;
  min-height: 42px;
  color: var(--pe-ink);
  background: var(--pe-paper);
  border: 1px solid #c9c5b8;
  border-radius: 9px;
  box-shadow: 0 3px 14px #302e2619;
  font-size: 13px;
  font-weight: 700;
}
.pe-launcher:hover { background: var(--pe-soft); }

.pe-panel {
  position: fixed;
  z-index: 100020;
  inset: 0 0 0 auto;
  width: var(--pe-panel-width);
  height: 100vh;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  background: var(--pe-paper);
  border-left: 1px solid var(--pe-line);
  box-shadow: -5px 0 26px #302e2612;
  overscroll-behavior: contain;
}
.pe-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: max(22px, env(safe-area-inset-top)) 20px 16px;
}
.pe-eyebrow { color: #7a725f; font-size: 9px; font-weight: 700; letter-spacing: 1.5px; margin-bottom: 5px !important; }
.pe-heading { font-size: 19px; line-height: 1.15; letter-spacing: -.45px; font-weight: 700; }
.pe-status-row { display: flex; gap: 7px; align-items: center; padding: 0 20px 16px; border-bottom: 1px solid var(--pe-line); }
.pe-status-dot { width: 6px; height: 6px; flex: 0 0 6px; border-radius: 50%; background: var(--pe-accent); }
.pe-status { color: var(--pe-muted); font-size: 11px; overflow-wrap: anywhere; }
.pe-status-error .pe-status { color: #9c4633; font-weight: 700; }
.pe-status-error .pe-status-dot { background: #9c4633; }
.pe-scroll { overflow-y: auto; flex: 1; padding: 18px 20px max(20px, env(safe-area-inset-bottom)); scrollbar-width: thin; }
.pe-history, .pe-backup-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.pe-history { margin-bottom: 22px; }
.pe-slide-label { color: var(--pe-muted); font-size: 11px; font-weight: 700; margin-bottom: 8px !important; overflow-wrap: anywhere; }
.pe-selection { background: var(--pe-soft); border: 1px solid var(--pe-line); border-radius: 9px; padding: 12px; margin-bottom: 16px; }
.pe-selection-caption { display: block; color: #7a725f; font-size: 9px; letter-spacing: 1.25px; font-weight: 700; margin-bottom: 5px; }
.pe-selection-label { color: var(--pe-ink); font-size: 13px; line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.pe-empty-state { color: var(--pe-muted); font-size: 13px; line-height: 1.65; padding: 4px 0 20px; }
.pe-tabs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; border-bottom: 1px solid var(--pe-line); margin-bottom: 18px; }
.pe-tab { color: var(--pe-muted); background: transparent; border: 0; border-bottom: 2px solid transparent; padding: 10px 7px; font-size: 12px; font-weight: 700; border-radius: 3px 3px 0 0; }
.pe-tab[aria-selected="true"] { color: var(--pe-accent-dark); border-bottom-color: var(--pe-accent); }
.pe-tab:hover:not(:disabled) { background: var(--pe-soft); }
.pe-field { margin-bottom: 14px; min-width: 0; }
.pe-label { display: block; margin-bottom: 6px; font-size: 12px; font-weight: 700; }
.pe-input { display: block; width: 100%; min-height: 39px; border: 1px solid #cfc8b9; border-radius: 6px; padding: 9px 10px; color: var(--pe-ink); background: #fff; box-shadow: none; }
.pe-input:focus { border-color: var(--pe-accent); }
textarea.pe-input { resize: vertical; line-height: 1.55; max-height: 38vh; min-height: 72px; }
.pe-text-input { min-height: 140px !important; }
.pe-file-input { max-width: 100%; width: 100%; color: var(--pe-muted); font-size: 11px !important; border: 1px solid #cfc8b9; border-radius: 6px; padding: 5px; background: #fff; }
.pe-file-input::file-selector-button { background: var(--pe-soft); color: var(--pe-ink); border: 0; border-radius: 3px; padding: 8px; margin-right: 7px; font: inherit; font-weight: 700; cursor: pointer; }
.pe-hint { color: var(--pe-muted); font-size: 11px; line-height: 1.55; margin-top: 7px !important; }
.pe-help { color: var(--pe-muted); font-size: 12px; line-height: 1.65; }
.pe-motion-label { color: var(--pe-muted); font-size: 11px; line-height: 1.5; margin-bottom: 14px !important; }
.pe-timing-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.pe-timing-row .pe-field { margin-bottom: 0; }
.pe-button { display: inline-flex; align-items: center; justify-content: center; min-height: 38px; border: 1px solid transparent; border-radius: 6px; padding: 9px 12px; font-size: 12px !important; font-weight: 700 !important; line-height: 1.25; text-decoration: none; transition: background .15s ease, border-color .15s ease; }
.pe-button-primary { color: #fff; background: var(--pe-accent); border-color: var(--pe-accent); }
.pe-button-primary:hover:not(:disabled) { background: var(--pe-accent-dark); border-color: var(--pe-accent-dark); }
.pe-button-secondary { color: #504b3d; background: #fffdf8; border-color: #d4cebf; }
.pe-button-secondary:hover:not(:disabled) { background: var(--pe-soft); border-color: #a49d8b; }
.pe-button-quiet { background: var(--pe-soft); color: #514f40; }
.pe-button-quiet:hover { background: #e7e3d6; }
.pe-close { min-height: 34px; padding: 8px 11px; white-space: nowrap; flex-shrink: 0; font-size: 11px !important; }
.pe-full { width: 100%; }
.pe-tab-panel > .pe-button { margin-top: 10px; }
.pe-button-link { padding-left: 0; padding-right: 0; background: transparent; color: #8f4931; border: 0; text-decoration: underline; text-underline-offset: 3px; }
.pe-button-link:hover { color: #622e1c; }
.pe-sharing { border-top: 1px solid var(--pe-line); margin-top: 24px; padding-top: 20px; }
.pe-section-heading { font-size: 13px; font-weight: 700; margin-bottom: 6px !important; }
.pe-publish-steps { list-style: decimal; margin: 16px 0 20px; padding-left: 18px; }
.pe-publish-step { padding-left: 3px; margin-bottom: 18px; color: var(--pe-accent-dark); font-size: 12px; }
.pe-publish-step::marker { font-weight: 700; }
.pe-step-heading { color: var(--pe-ink); font-size: 12px; line-height: 1.4; font-weight: 700; margin: 0 0 8px; }
.pe-github-upload { text-align: center; }
.pe-root a:focus-visible { outline: 3px solid #b36b2d; outline-offset: 3px; }
.pe-backup-row .pe-button { font-size: 11px !important; padding: 9px 7px; }
.pe-reset { margin-top: 12px; font-size: 11px !important; }
.pe-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.pe-dialog-overlay { position: fixed; z-index: 100030; inset: 0; display: flex; align-items: center; justify-content: center; padding: 24px; background: #26251f66; }
.pe-dialog { width: min(410px, 100%); border: 1px solid var(--pe-line); background: var(--pe-paper); border-radius: 12px; padding: 24px; box-shadow: 0 15px 60px #24231940; }
.pe-dialog-heading { font-size: 20px; line-height: 1.2; font-weight: 700; margin-bottom: 12px !important; }
.pe-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 22px; }
.pe-button-danger { color: #fff; background: #9c4633; border-color: #9c4633; }
.pe-button-danger:hover { background: #793021; }

@media (max-width: 899px) {
  .pe-panel { inset: auto 0 0; width: 100%; height: 55vh; height: 55dvh; border-left: 0; border-top: 1px solid var(--pe-line); box-shadow: 0 -5px 24px #302e2612; }
  .pe-header { padding: 12px 20px 10px; }
  .pe-status-row { padding-bottom: 10px; }
  .pe-scroll { padding-top: 14px; }
}

@media (max-width: 680px) {
  .pe-launcher { top: max(9px, env(safe-area-inset-top)); right: max(10px, env(safe-area-inset-right)); padding: 8px 12px; min-height: 36px; font-size: 11px; }
  .pe-header { padding: 12px 15px 10px; gap: 8px; }
  .pe-heading { font-size: 17px; }
  .pe-status-row { padding-left: 15px; padding-right: 15px; }
  .pe-scroll { padding-left: 15px; padding-right: 15px; }
  .pe-dialog-overlay { padding: 16px; }
  .pe-dialog { padding: 20px; }
  .pe-input { font-size: 16px !important; }
}

@media (prefers-reduced-motion: reduce) {
  .pe-root *, .pe-root *::before, .pe-root *::after { transition: none !important; animation: none !important; }
}

@media print { .pe-root { display: none !important; } }

/* Editing affects the workspace only; presentation mode keeps authored motion. */
body[data-pe-editing]:not([data-pe-preview]) deck-stage > section,
body[data-pe-editing]:not([data-pe-preview]) deck-stage > section *,
body[data-pe-editing]:not([data-pe-preview]) deck-stage > section [data-a],
body[data-pe-editing]:not([data-pe-preview]) deck-stage > section [data-pe-effect] {
  animation: none !important;
  transition: none !important;
}
body[data-pe-editing] deck-stage > section [data-pe-id] { cursor: pointer; }
body[data-pe-editing] deck-stage > section [data-pe-selected] {
  outline: 4px solid #a65427 !important;
  outline-offset: 7px;
}
body[data-pe-editing] deck-stage > section [data-pe-hover]:not([data-pe-selected]) {
  outline: 3px dashed #a65427;
  outline-offset: 5px;
}
@keyframes pe-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pe-up { from { opacity: 0; translate: 0 46px; } to { opacity: 1; translate: 0 0; } }
@keyframes pe-down { from { opacity: 0; translate: 0 -46px; } to { opacity: 1; translate: 0 0; } }
@keyframes pe-left { from { opacity: 0; translate: 46px 0; } to { opacity: 1; translate: 0 0; } }
@keyframes pe-right { from { opacity: 0; translate: -46px 0; } to { opacity: 1; translate: 0 0; } }
@keyframes pe-zoom { from { opacity: 0; scale: .75; } to { opacity: 1; scale: 1; } }
@keyframes pe-pop { 0% { opacity: 0; scale: .65; } 75% { opacity: 1; scale: 1.06; } 100% { opacity: 1; scale: 1; } }
@media (prefers-reduced-motion: no-preference) {
  [data-deck-active] [data-pe-effect]:not([data-pe-effect="none"]) {
    animation: var(--pe-animation) var(--pe-duration, 800ms) ease var(--pe-delay, 0ms) both !important;
    transform-box: fill-box;
    transform-origin: center;
  }
}
[data-deck-active] [data-pe-effect="none"] { animation: none !important; }
@media print {
  #pe-editor, .pe-editor, [data-pe-ui] { display: none !important; }
  [data-pe-selected], [data-pe-hover] { outline: none !important; }
}

core:
(function () {
  'use strict';

  const EFFECTS = new Set(['original', 'none', 'fade', 'up', 'down', 'left', 'right', 'zoom', 'pop']);
  const DURATIONS = {up: 800, fade: 1000, pop: 700, draw: 1800, growx: 1100, growy: 1100, flow: 1400, beat: 1800, float: 6000, dot: 3000};
  const FORMAT = 'acute-exercise-editor';
  const DEFAULT_DECK = 'acute-exercise-v1';
  const STUDIO_NAMESPACE = 'presentation-editor-studio';
  const MAX_DOWNLOAD = 25 * 1024 * 1024;
  const motionProperties = ['animation-duration', 'animation-delay', '--pe-animation', '--pe-duration', '--pe-delay'];
  const plain = value => value && typeof value === 'object' && !Array.isArray(value) && [Object.prototype, null].includes(Object.getPrototypeOf(value));
  const shorten = value => String(value).replace(/\s+/g, ' ').trim().slice(0, 72);
  const milliseconds = (value, fallback) => value ? parseFloat(value) * (value.endsWith('ms') ? 1 : 1000) : fallback;
  const identifier = value => typeof value === 'string' && value.trim().length > 0 && value.length <= 200;

  function readStudioContext() {
    const value = window.__peStudioContext;
    if (value === undefined || value === null) return null;
    let origin;
    try { origin = new URL(value.parentOrigin); } catch (_) { throw new Error('The Studio parent origin is invalid.'); }
    if (!plain(value) || window.parent === window || !identifier(value.channel) || value.channel.length < 16 ||
        !identifier(value.deckId) || !identifier(value.documentId) || !['edit', 'present'].includes(value.mode) ||
        !['http:', 'https:'].includes(origin.protocol) || origin.origin !== value.parentOrigin) {
      throw new Error('The Studio connection settings are invalid.');
    }
    return Object.freeze({channel: value.channel, parentOrigin: value.parentOrigin, deckId: value.deckId,
      documentId: value.documentId, mode: value.mode,
      ...(Object.prototype.hasOwnProperty.call(value, 'patches') ? {patches: value.patches} : {})});
  }

  function start(deck) {
    const files = window.PresentationEditorFiles;
    const studio = readStudioContext();
    const deckId = studio ? studio.deckId : identifier(window.__peSeed && window.__peSeed.deckId) ? window.__peSeed.deckId : DEFAULT_DECK;
    const slides = Array.from(deck.children).filter(el => el.tagName === 'SECTION');
    const records = new Map();
    const slideItems = slides.map(() => []);
    const textRecords = new WeakMap();
    const imageRecords = new WeakMap();
    const motionRecords = new WeakMap();
    let patches = {};
    let rendered = {};
    let selectedId = null;
    let open = false;
    let ui;
    let status = studio ? 'Loading your saved presentation…' : 'Published presentation. Edits are saved as a browser draft.';
    let statusKind = 'normal';
    let undo = [];
    let redo = [];
    let saveTimer;
    let saveVersion = 0;
    let previewTimer;
    let availableDraft = null;
    let draftChecked = false;
    let draftApplied = false;
    let hasEdited = false;
    let mutationEpoch = 0;
    let pendingOperation = 0;
    let seed;
    let studioLoaded = !studio;
    let studioRevision = 0;
    let studioSavedRevision = 0;
    let studioSaving = false;

    function postStudio(type, detail) {
      if (!studio) return;
      window.parent.postMessage({namespace: STUDIO_NAMESPACE, version: 1, channel: studio.channel,
        type, deckId, documentId: studio.documentId, revision: studioRevision, ...detail}, studio.parentOrigin);
    }

    function requireLoaded() {
      if (studio && !studioLoaded) throw new Error('Wait for your saved presentation to finish loading.');
    }

    function motionFor(element, slideIndex) {
      const target = element.closest('[data-a]') || element;
      let record = motionRecords.get(target);
      if (record) return record;
      const id = target.dataset.peId + '-m';
      const original = target.getAttribute('data-a');
      const duration = milliseconds(target.style.animationDuration, DURATIONS[original] || 800);
      const delay = milliseconds(target.style.animationDelay, 0);
      record = {id, type: 'motion', element: target, slideIndex, original,
        baseline: {effect: 'original', duration, delay},
        style: motionProperties.map(name => [name, target.style.getPropertyValue(name), target.style.getPropertyPriority(name)])};
      records.set(id, record);
      motionRecords.set(target, record);
      return record;
    }

    slides.forEach((slide, slideIndex) => {
      slide.querySelectorAll('[data-pe-id]').forEach(element => {
        if (element.closest('script,style,defs')) return;
        if (element.tagName === 'IMG') {
          const record = {id: element.dataset.peId + '-i', type: 'image', element, slideIndex,
            baseline: {src: element.getAttribute('src'), alt: element.getAttribute('alt') || ''}};
          record.motion = motionFor(element, slideIndex);
          records.set(record.id, record);
          imageRecords.set(element, record);
          slideItems[slideIndex].push(record);
        }
        Array.from(element.childNodes).forEach((node, index) => {
          if (node.nodeType !== Node.TEXT_NODE || !node.nodeValue.trim()) return;
          const record = {id: element.dataset.peId + '-t' + index, type: 'text', element, node, slideIndex, baseline: node.nodeValue};
          record.motion = motionFor(element, slideIndex);
          records.set(record.id, record);
          textRecords.set(node, record);
          slideItems[slideIndex].push(record);
        });
      });
      slide.querySelectorAll('[data-a]').forEach(element => {
        const record = motionFor(element, slideIndex);
        slideItems[slideIndex].push(record);
      });
    });

    function validateState(value) {
      if (!plain(value) || value.format !== FORMAT || value.version !== 1 || value.deckId !== deckId ||
          typeof value.documentId !== 'string' || !value.documentId || value.documentId.length > 200 || !plain(value.patches)) {
        throw new Error('This changes file belongs to a different presentation or editor version.');
      }
      if (Object.keys(value.patches).length > records.size) throw new Error('The changes file contains too many edits.');
      const clean = {};
      let totalSize = 0;
      for (const [id, patch] of Object.entries(value.patches)) {
        const record = records.get(id);
        if (!record || !plain(patch)) throw new Error('The changes file contains an unknown slide item.');
        if (record.type === 'text') {
          if (Object.keys(patch).some(key => key !== 'text') || typeof patch.text !== 'string' || patch.text.length > 10000) throw new Error('A text edit is invalid or too long (maximum 10,000 characters).');
          clean[id] = {text: patch.text};
          totalSize += patch.text.length;
        } else if (record.type === 'image') {
          if (Object.keys(patch).some(key => !['src', 'alt'].includes(key)) || typeof patch.alt !== 'string' || patch.alt.length > 2000 ||
              (patch.src !== undefined && (typeof patch.src !== 'string' || patch.src.length > 14 * 1024 * 1024 || !/^data:image\/(?:png|jpeg|gif|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(patch.src)))) {
            throw new Error('An image edit is invalid. Use a PNG, JPEG, WebP, or GIF image up to 10 MB.');
          }
          clean[id] = patch.src === undefined ? {alt: patch.alt} : {src: patch.src, alt: patch.alt};
          totalSize += (patch.src || '').length + patch.alt.length;
        } else {
          if (Object.keys(patch).some(key => !['effect', 'duration', 'delay'].includes(key)) || !EFFECTS.has(patch.effect) ||
              !Number.isFinite(patch.duration) || patch.duration < 100 || patch.duration > 10000 ||
              !Number.isFinite(patch.delay) || patch.delay < 0 || patch.delay > 10000) throw new Error('An animation setting is invalid.');
          clean[id] = {effect: patch.effect, duration: patch.duration, delay: patch.delay};
        }
        if (totalSize > 19 * 1024 * 1024) throw new Error(studio ? 'These changes are too large. Use smaller replacement images.' : 'These changes are too large to publish through GitHub. Use smaller replacement images.');
      }
      return {format: FORMAT, version: 1, deckId, documentId: value.documentId, patches: clean};
    }

    function currentState(documentId) {
      return {format: FORMAT, version: 1, deckId, documentId: documentId || seed.documentId, patches: {...patches}};
    }

    function applyAll() {
      const changed = new Set([...Object.keys(rendered), ...Object.keys(patches)]);
      changed.forEach(id => {
        if (rendered[id] === patches[id]) return;
        const record = records.get(id);
        const patch = patches[id];
        if (record.type === 'text') record.node.nodeValue = patch ? patch.text : record.baseline;
        else if (record.type === 'image') {
          const src = patch && patch.src || record.baseline.src;
          if (record.element.getAttribute('src') !== src) record.element.setAttribute('src', src);
          record.element.setAttribute('alt', patch ? patch.alt : record.baseline.alt);
        } else {
          const element = record.element;
          element.removeAttribute('data-pe-effect');
          record.style.forEach(([name, value, priority]) => {
            if (value) element.style.setProperty(name, value, priority);
            else element.style.removeProperty(name);
          });
          if (patch) {
            if (patch.effect === 'original') {
              element.style.setProperty('animation-duration', patch.duration + 'ms', 'important');
              element.style.setProperty('animation-delay', patch.delay + 'ms', 'important');
            } else {
              element.dataset.peEffect = patch.effect;
              element.style.setProperty('--pe-animation', 'pe-' + patch.effect);
              element.style.setProperty('--pe-duration', patch.duration + 'ms');
              element.style.setProperty('--pe-delay', patch.delay + 'ms');
            }
          }
        }
      });
      rendered = {...patches};
    }

    function label(record) {
      if (record.type === 'text') return 'Text · ' + (shorten(record.node.nodeValue) || '(empty)');
      if (record.type === 'image') return 'Image · ' + (shorten(record.element.getAttribute('alt')) || 'Slide image');
      const text = shorten(record.element.textContent);
      return 'Motion · ' + (text || record.element.tagName.toLowerCase() + ' — ' + (record.original || 'none'));
    }

    function render() {
      const record = records.get(selectedId);
      const motion = record && (record.type === 'motion' ? record : record.motion);
      ui.render({slideLabel: 'Slide ' + (deck.index + 1) + ' of ' + slides.length,
        items: slideItems[deck.index].map(item => ({id: item.id, type: item.type, label: label(item)})),
        selected: record ? {id: record.id, type: record.type, label: label(record),
          text: record.type === 'text' ? record.node.nodeValue : undefined,
          alt: record.type === 'image' ? record.element.getAttribute('alt') || '' : undefined,
          motion: patches[motion.id] || motion.baseline,
          motionLabel: motion.element === record.element ? 'Applies to this item' : 'Applies to the containing animation group'} : null,
        status, statusKind, canUndo: undo.length > 0, canRedo: redo.length > 0,
        loading: studio && !studioLoaded, saving: studioSaving,
        dirty: studio ? studioRevision !== studioSavedRevision : Object.keys(patches).length > 0});
    }

    function message(text, error) {
      status = text;
      statusKind = error ? 'error' : 'normal';
      if (ui) render();
    }

    function select(id) {
      deck.querySelectorAll('[data-pe-selected]').forEach(el => el.removeAttribute('data-pe-selected'));
      const record = records.get(id);
      selectedId = record && record.slideIndex === deck.index ? id : null;
      if (selectedId && open) record.element.setAttribute('data-pe-selected', '');
      render();
    }

    function saveSoon() {
      if (studio) {
        studioRevision++;
        studioSaving = false;
        message('Changes are waiting to be saved online.');
        postStudio('changes', {state: currentState()});
        return;
      }
      clearTimeout(saveTimer);
      const version = ++saveVersion;
      message('Saving draft on this browser…');
      const state = currentState();
      saveTimer = setTimeout(async () => {
        try {
          await files.saveDraft(seed.documentId, state);
          if (version === saveVersion) message('Draft saved on this browser. Download to publish.');
        } catch (error) {
          if (version === saveVersion) message(error.message, true);
        }
      }, 300);
    }

    function commit(next) {
      requireLoaded();
      mutationEpoch++;
      const clean = validateState({...currentState(), patches: next}).patches;
      if (JSON.stringify(clean) === JSON.stringify(patches)) return;
      undo.push(patches);
      if (undo.length > 60) undo.shift();
      redo = [];
      patches = clean;
      hasEdited = true;
      stopPreview();
      applyAll();
      render();
      saveSoon();
    }

    function changeOne(id, patch) {
      commit({...patches, [id]: patch});
    }

    function history(backward) {
      requireLoaded();
      mutationEpoch++;
      const from = backward ? undo : redo;
      const to = backward ? redo : undo;
      if (!from.length) return;
      to.push(patches);
      patches = from.pop();
      hasEdited = true;
      stopPreview();
      applyAll();
      render();
      saveSoon();
    }

    function stopPreview() {
      clearTimeout(previewTimer);
      document.body.removeAttribute('data-pe-preview');
    }

    function replay() {
      stopPreview();
      const slide = slides[deck.index];
      slide.removeAttribute('data-deck-active');
      void slide.offsetWidth;
      document.body.setAttribute('data-pe-preview', '');
      slide.setAttribute('data-deck-active', '');
      const item = records.get(selectedId);
      const motion = item && (item.type === 'motion' ? item : item.motion);
      const settings = motion && (patches[motion.id] || motion.baseline);
      previewTimer = setTimeout(stopPreview, Math.max(4000, settings ? settings.duration + settings.delay + 1000 : 6000));
    }

    // Reserve room for the editor without changing any authored slide geometry.
    const originalFit = deck._fit.bind(deck);
    deck._fit = function () {
      originalFit();
      const stage = deck.shadowRoot.querySelector('.stage');
      const canvas = deck.shadowRoot.querySelector('.canvas');
      const overlay = deck.shadowRoot.querySelector('.overlay');
      if (!stage || !canvas) return;
      const mobile = window.innerWidth < 900;
      const right = open && !mobile ? ui.panel.getBoundingClientRect().width : 0;
      const bottom = open && mobile ? ui.panel.getBoundingClientRect().height : 0;
      stage.style.right = right + 'px';
      stage.style.bottom = bottom + 'px';
      if (overlay) {
        overlay.style.marginLeft = (deck._railWidth() - right) / 2 + 'px';
        overlay.style.bottom = bottom ? bottom + 8 + 'px' : '';
      }
      if (open) {
        // A transient oversized panel must never produce a negative scale,
        // which flips the slide while styles or viewport dimensions settle.
        canvas.style.transform = 'scale(' + Math.min(Math.max(1, window.innerWidth - deck._railWidth() - right) / deck.designWidth,
          Math.max(1, window.innerHeight - bottom) / deck.designHeight) + ')';
      }
    };

    function resumeDraft() {
      if (studio) return;
      if (draftApplied || !draftChecked || !open) return;
      draftApplied = true;
      if (availableDraft && !hasEdited) {
        patches = availableDraft.patches;
        applyAll();
        message('Restored your browser draft. Download to publish.');
      }
    }

    function toggle(value, notifyParent = true) {
      open = value;
      document.body.toggleAttribute('data-pe-editing', open);
      stopPreview();
      resumeDraft();
      if (!open) {
        deck.querySelectorAll('[data-pe-selected],[data-pe-hover]').forEach(el => {
          el.removeAttribute('data-pe-selected'); el.removeAttribute('data-pe-hover');
        });
      } else if (selectedId) select(selectedId);
      deck._fit();
      if (!open) {
        const slide = slides[deck.index];
        slide.removeAttribute('data-deck-active');
        void slide.offsetWidth;
        slide.setAttribute('data-deck-active', '');
      }
      if (studio && notifyParent) postStudio('mode-change', {mode: open ? 'edit' : 'present'});
    }

    const safeAction = action => async (...args) => {
      try { return await action(...args); }
      catch (error) { message(error.message || 'The change could not be applied.', true); }
    };

    ui = new window.PresentationEditorUI({
      onToggle: toggle, onSelect: select, onUndo: safeAction(() => history(true)), onRedo: safeAction(() => history(false)),
      onApplyText: safeAction(text => {
        const record = records.get(selectedId);
        if (record && record.type === 'text') changeOne(record.id, {text});
      }),
      onReplaceImage: safeAction(async (file, alt) => {
        const record = records.get(selectedId);
        if (!record || record.type !== 'image') return;
        const epoch = mutationEpoch;
        const operation = ++pendingOperation;
        const src = file ? (await files.readImage(file)).dataURL : (patches[record.id] || {}).src;
        if (epoch !== mutationEpoch || operation !== pendingOperation) { message('Image replacement cancelled because the draft changed. Please apply it again.'); return; }
        changeOne(record.id, src === undefined ? {alt} : {src, alt});
      }),
      onApplyMotion: safeAction(settings => {
        const record = records.get(selectedId);
        if (record) changeOne((record.type === 'motion' ? record : record.motion).id, settings);
      }),
      onPreview: replay,
      onSaveOnline: safeAction(() => {
        requireLoaded();
        if (!studio) return;
        studioSaving = true;
        message('Saving your presentation online…');
        postStudio('save-request', {state: currentState()});
      }),
      onDownload: safeAction(() => {
        requireLoaded();
        if (studio) {
          postStudio('download-request', {kind: 'html', filename: 'index.html', state: currentState()});
          message('Preparing your presentation backup…');
          return;
        }
        const id = 'acute-exercise-' + (crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.random().toString(36).slice(2));
        const blob = files.buildExport(window.__peBundleHtml, currentState(id));
        if (blob.size > MAX_DOWNLOAD) throw new Error('This file is larger than GitHub’s 25 MB upload limit. Use smaller replacement images.');
        files.download(blob, 'index.html');
        message('Download ready. Upload index.html to GitHub to update the shared link.');
      }),
      onExport: safeAction(() => {
        requireLoaded();
        if (studio) {
          postStudio('download-request', {kind: 'changes', filename: 'presentation-changes.json', state: currentState()});
          message('Preparing your changes backup…');
          return;
        }
        files.download(new Blob([JSON.stringify(currentState(), null, 2)], {type: 'application/json'}), 'presentation-changes.json');
        message('Changes exported as a backup.');
      }),
      onImport: safeAction(async file => {
        requireLoaded();
        const epoch = mutationEpoch;
        const operation = ++pendingOperation;
        const imported = validateState(await files.readChanges(file));
        // Decode every imported raster before applying any edits, so broken or
        // disguised image data cannot replace a working picture.
        for (const patch of Object.values(imported.patches)) {
          if (!patch.src) continue;
          const blob = await (await fetch(patch.src)).blob();
          await files.readImage(blob);
        }
        if (epoch !== mutationEpoch || operation !== pendingOperation) { message('Import cancelled because the draft changed. Please import again.'); return; }
        commit(imported.patches);
      }),
      // Studio's seed is the last saved cloud state. Reset removes those edits
      // too; a standalone file keeps its published version as the baseline.
      onReset: safeAction(() => commit(studio ? {} : {...seed.patches}))
    }, {studio: Boolean(studio)});
    ui.root.addEventListener('keydown', event => event.stopPropagation());
    ui.textInput.maxLength = 10000;
    ui.altInput.maxLength = 2000;

    function clickedRecord(event) {
      const target = event.target instanceof Element ? event.target : event.target.parentElement;
      const slide = target.closest('section[data-deck-active]');
      if (!slide || slide.parentElement !== deck) return null;
      const img = target.closest('img');
      if (img && imageRecords.has(img)) return imageRecords.get(img);
      const caret = document.caretPositionFromPoint ? document.caretPositionFromPoint(event.clientX, event.clientY) :
        document.caretRangeFromPoint ? document.caretRangeFromPoint(event.clientX, event.clientY) : null;
      const node = caret && (caret.offsetNode || caret.startContainer);
      if (node && target.contains(node) && textRecords.has(node)) return textRecords.get(node);
      for (let element = target; element && element !== slide; element = element.parentElement) {
        for (const node of element.childNodes) if (textRecords.has(node)) return textRecords.get(node);
        if (motionRecords.has(element)) return motionRecords.get(element);
      }
      return null;
    }

    deck.addEventListener('click', event => {
      if (!open || !(event.target instanceof Element) || !event.target.closest('section[data-deck-active]')) return;
      event.preventDefault();
      event.stopPropagation();
      const record = clickedRecord(event);
      if (record) select(record.id);
    }, true);
    deck.addEventListener('pointermove', event => {
      if (!open) return;
      const record = clickedRecord(event);
      const previous = deck.querySelector('[data-pe-hover]');
      if (previous && (!record || previous !== record.element)) previous.removeAttribute('data-pe-hover');
      if (record && previous !== record.element) record.element.setAttribute('data-pe-hover', '');
    });
    deck.addEventListener('pointerleave', () => {
      deck.querySelectorAll('[data-pe-hover]').forEach(el => el.removeAttribute('data-pe-hover'));
    });
    deck.addEventListener('slidechange', () => {
      stopPreview();
      select(null);
    });
    // The exported viewer's slide-reordering menu depends on its authoring host.
    // Leave navigation enabled, but don't offer unsupported structural edits.
    deck.addEventListener('keydown', event => {
      if (['Delete', 'Backspace'].includes(event.key) && event.composedPath().some(el => el.classList && el.classList.contains('rail'))) {
        event.preventDefault(); event.stopPropagation();
      }
    }, true);
    ['contextmenu', 'dragstart'].forEach(name => deck.addEventListener(name, event => {
      if (event.composedPath().some(el => el.classList && el.classList.contains('rail'))) {
        event.preventDefault(); event.stopPropagation();
      }
    }, true));

    function applyStudioState(value) {
      const loaded = validateState(value);
      if (loaded.documentId !== studio.documentId) throw new Error('This saved state belongs to a different Studio document.');
      mutationEpoch++;
      pendingOperation++;
      seed = loaded;
      patches = loaded.patches;
      undo = [];
      redo = [];
      hasEdited = false;
      // Keep revisions monotonic across a later parent refresh so an older
      // in-flight save acknowledgement cannot mark newer edits as saved.
      if (studioLoaded) studioRevision++;
      studioSavedRevision = studioRevision;
      studioSaving = false;
      studioLoaded = true;
      stopPreview();
      applyAll();
      message('Saved presentation loaded. Changes save online.');
    }

    if (studio) {
      seed = {format: FORMAT, version: 1, deckId, documentId: studio.documentId, patches: {}};
      window.addEventListener('message', event => {
        if (!event.isTrusted || event.source !== window.parent || event.origin !== studio.parentOrigin) return;
        const data = event.data;
        if (!plain(data) || data.namespace !== STUDIO_NAMESPACE || data.version !== 1 || data.channel !== studio.channel ||
            data.deckId !== deckId || data.documentId !== studio.documentId) return;
        try {
          if (data.type === 'load-state') {
            applyStudioState(data.state);
            postStudio('state-loaded', {loaded: true});
          } else if (data.type === 'save-status') {
            if (typeof data.message !== 'string' || data.message.length > 2000 ||
                !['normal', 'success', 'saved', 'saving', 'error'].includes(data.kind)) return;
            const acknowledged = Number.isSafeInteger(data.revision) ? data.revision : studioRevision;
            if (acknowledged < 0 || acknowledged > studioRevision) return;
            if (data.kind === 'saving') {
              if (acknowledged === studioRevision) { studioSaving = true; message(data.message); }
              return;
            }
            studioSaving = false;
            if (data.kind !== 'error') studioSavedRevision = Math.max(studioSavedRevision, acknowledged);
            if (acknowledged === studioRevision) message(data.message, data.kind === 'error');
            else if (data.kind !== 'error') message('Earlier changes saved. Newer changes are waiting to be saved online.');
            else render();
          } else if (data.type === 'set-mode' && ['edit', 'present'].includes(data.mode)) {
            ui.setOpen(data.mode === 'edit');
            toggle(data.mode === 'edit', false);
          }
        } catch (error) {
          message(error.message || 'The Studio update could not be applied.', true);
          postStudio('state-error', {message: String(error.message || 'The Studio update could not be applied.').slice(0, 2000)});
        }
      });
      if (Object.prototype.hasOwnProperty.call(studio, 'patches')) {
        try { applyStudioState({...seed, patches: studio.patches}); }
        catch (error) { message('Saved edits could not be loaded: ' + error.message, true); }
      }
    } else {
      try {
        seed = validateState(window.__peSeed);
      } catch (error) {
        seed = {format: FORMAT, version: 1, deckId, documentId: 'acute-exercise-main-v1', patches: {}};
        message('Saved edits could not be loaded: ' + error.message, true);
      }
    }
    patches = seed.patches;
    applyAll();
    render();
    if (!studio) {
      files.loadDraft(seed.documentId).then(value => {
        if (value) availableDraft = validateState(value);
        draftChecked = true;
        resumeDraft();
      }).catch(error => { draftChecked = true; message(error.message, true); });
    }
    document.body.setAttribute('data-pe-ready', '');
    if (studio) {
      ui.setOpen(studio.mode === 'edit');
      toggle(studio.mode === 'edit', false);
      postStudio('ready', {slideCount: slides.length, loaded: studioLoaded,
        items: Array.from(records.values(), record => ({id: record.id, type: record.type, slideIndex: record.slideIndex,
          elementId: record.element.dataset.peId,
          ...(record.type === 'motion' ? {original: record.original, duration: record.baseline.duration, delay: record.baseline.delay}
            : {motionId: record.motion.id})}))});
    } else if (new URLSearchParams(location.search).get('edit') === '1') { ui.setOpen(true); toggle(true); }
  }

  let attempts = 0;
  function ready() {
    const deck = document.querySelector('deck-stage');
    if (deck && typeof deck._fit === 'function' && deck.length > 0 && deck.shadowRoot && deck.shadowRoot.querySelector('.canvas')) {
      try { start(deck); }
      catch (error) { console.error('The presentation editor could not initialize:', error); }
    } else if (++attempts < 200) setTimeout(ready, 50);
    else console.error('The presentation editor could not initialize. Reload the page to try again.');
  }
  ready();
})();

ui:
(function () {
  'use strict';

  function element(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function button(text, className, action) {
    var node = element('button', className, text);
    node.type = 'button';
    if (action) node.addEventListener('click', action);
    return node;
  }

  function setText(node, value) {
    value = value === undefined || value === null ? '' : String(value);
    if (node.textContent !== value) node.textContent = value;
  }

  function field(label, control, hint) {
    var group = element('div', 'pe-field');
    var labelNode = element('label', 'pe-label', label);
    labelNode.htmlFor = control.id;
    group.append(labelNode, control);
    if (hint) {
      var help = element('p', 'pe-hint', hint);
      help.id = control.id + '-help';
      control.setAttribute('aria-describedby', help.id);
      group.append(help);
    }
    return group;
  }

  class PresentationEditorUI {
    constructor(callbacks, settings) {
      this.callbacks = callbacks || {};
      this.settings = settings || {};
      this.studio = Boolean(this.settings.studio);
      this.open = false;
      this.selected = null;
      this.activeTab = 'text';
      this.pendingImage = null;
      this.lastSelectionSignature = '';
      this.idPrefix = 'pe-' + Math.random().toString(36).slice(2, 8);
      this.root = element('div', 'pe-root');
      this.element = this.root;
      this.root.dataset.presentationEditorUi = 'true';
      this.root.dataset.peWorkspace = this.studio ? 'studio' : 'standalone';

      this.launcher = button('Edit presentation', 'pe-launcher', () => this.toggle(true));
      this.launcher.setAttribute('aria-expanded', 'false');
      this.launcher.setAttribute('aria-controls', this.idPrefix + '-panel');
      this.root.append(this.launcher);

      this.panel = element('aside', 'pe-panel');
      this.panel.id = this.idPrefix + '-panel';
      this.panel.setAttribute('aria-label', 'Presentation editor');
      this.panel.hidden = true;
      this.root.append(this.panel);

      var header = element('div', 'pe-header');
      var titleBlock = element('div');
      titleBlock.append(element('p', 'pe-eyebrow', 'PRESENTATION TOOLS'));
      var heading = element('h2', 'pe-heading', 'Edit presentation');
      titleBlock.append(heading);
      this.closeButton = button('Present', 'pe-button pe-button-quiet pe-close', () => this.toggle(false));
      this.closeButton.setAttribute('aria-label', 'Exit editor and present slides');
      header.append(titleBlock, this.closeButton);
      this.panel.append(header);

      var statusRow = element('div', 'pe-status-row');
      var dot = element('span', 'pe-status-dot');
      dot.setAttribute('aria-hidden', 'true');
      this.status = element('span', 'pe-status', 'Changes saved to this browser');
      this.status.setAttribute('role', 'status');
      this.status.setAttribute('aria-live', 'polite');
      statusRow.append(dot, this.status);
      this.panel.append(statusRow);

      var scrollArea = element('div', 'pe-scroll');
      this.panel.append(scrollArea);

      var history = element('div', 'pe-history');
      this.undoButton = button('Undo', 'pe-button pe-button-secondary', () => this.invoke('onUndo'));
      this.redoButton = button('Redo', 'pe-button pe-button-secondary', () => this.invoke('onRedo'));
      this.undoButton.disabled = true;
      this.redoButton.disabled = true;
      history.append(this.undoButton, this.redoButton);
      scrollArea.append(history);

      this.slideLabel = element('p', 'pe-slide-label', 'Current slide');
      scrollArea.append(this.slideLabel);
      this.itemsInput = element('select', 'pe-input');
      this.itemsInput.id = this.idPrefix + '-items';
      this.itemsInput.addEventListener('change', () => {
        if (this.itemsInput.value) this.invoke('onSelect', this.itemsInput.value);
      });
      scrollArea.append(field('Slide items', this.itemsInput, 'Select here or click an item on the slide.'));
      var selection = element('div', 'pe-selection');
      selection.append(element('span', 'pe-selection-caption', 'SELECTED ITEM'));
      this.selectionLabel = element('p', 'pe-selection-label', 'No item selected');
      selection.append(this.selectionLabel);
      scrollArea.append(selection);

      this.emptyState = element('p', 'pe-empty-state', 'Select an item on the slide to edit its text, image, or motion.');
      scrollArea.append(this.emptyState);

      this.tabs = element('div', 'pe-tabs');
      this.tabs.setAttribute('role', 'tablist');
      this.tabs.setAttribute('aria-label', 'Item settings');
      this.tabButtons = {};
      this.tabPanels = {};
      ['text', 'image', 'motion'].forEach((name) => {
        var tab = button(name.charAt(0).toUpperCase() + name.slice(1), 'pe-tab', () => this.activateTab(name, true));
        tab.id = this.idPrefix + '-tab-' + name;
        tab.setAttribute('role', 'tab');
        tab.setAttribute('aria-controls', this.idPrefix + '-settings-' + name);
        tab.setAttribute('aria-selected', 'false');
        tab.tabIndex = -1;
        tab.disabled = true;
        tab.addEventListener('keydown', (event) => this.navigateTabs(event, name));
        this.tabButtons[name] = tab;
        this.tabs.append(tab);
        var content = element('section', 'pe-tab-panel');
        content.id = this.idPrefix + '-settings-' + name;
        content.setAttribute('role', 'tabpanel');
        content.setAttribute('aria-labelledby', tab.id);
        content.hidden = true;
        this.tabPanels[name] = content;
      });
      scrollArea.append(this.tabs);
      Object.values(this.tabPanels).forEach((node) => scrollArea.append(node));
      this.buildTextPanel();
      this.buildImagePanel();
      this.buildMotionPanel();

      var sharing = element('section', 'pe-sharing');
      sharing.append(element('h3', 'pe-section-heading', 'Save & share'));
      this.sharingHelp = element('p', 'pe-help', this.studio ? 'Save your changes online to update this presentation. You can also download a backup.' : 'Changes save to this browser. Update the shared link in two steps.');
      sharing.append(this.sharingHelp);
      this.saveOnlineButton = button('Save online', 'pe-button pe-button-primary pe-full pe-save-online', () => this.invoke('onSaveOnline'));
      this.saveOnlineButton.hidden = !this.studio;
      sharing.append(this.saveOnlineButton);
      var publishSteps = element('ol', 'pe-publish-steps');
      var downloadStep = element('li', 'pe-publish-step');
      downloadStep.append(element('h4', 'pe-step-heading', 'Download your edits'));
      this.downloadButton = button(this.studio ? 'Download presentation backup' : 'Download updated index.html', 'pe-button pe-button-primary pe-full pe-download', () => this.invoke('onDownload'));
      downloadStep.append(this.downloadButton);
      downloadStep.append(element('p', 'pe-hint', 'Keep the filename index.html. If your browser adds a number, rename the file.'));
      var uploadStep = element('li', 'pe-publish-step');
      uploadStep.append(element('h4', 'pe-step-heading', 'Update the shared link'));
      this.githubUploadLink = element('a', 'pe-button pe-button-secondary pe-full pe-github-upload', 'Open GitHub upload');
      this.githubUploadLink.href = 'https://github.com/abody1217/acute-exercise-physiology/upload/main';
      this.githubUploadLink.target = '_blank';
      this.githubUploadLink.rel = 'noopener noreferrer';
      this.githubUploadLink.setAttribute('aria-label', 'Open GitHub upload in a new tab');
      uploadStep.append(this.githubUploadLink);
      uploadStep.append(element('p', 'pe-hint', 'Sign in with repository edit access. Replace index.html in the root folder, then commit changes to main. The shared link updates after deployment. Without GitHub access, send the downloaded index.html to the presentation owner to publish.'));
      publishSteps.append(downloadStep, uploadStep);
      if (this.studio) sharing.append(this.downloadButton);
      else sharing.append(publishSteps);
      var backupRow = element('div', 'pe-backup-row');
      this.exportChangesButton = button('Export changes', 'pe-button pe-button-secondary', () => this.invoke('onExport'));
      backupRow.append(this.exportChangesButton);
      this.importInput = element('input', 'pe-visually-hidden');
      this.importInput.type = 'file';
      this.importInput.accept = '.json,application/json';
      this.importInput.id = this.idPrefix + '-import';
      this.importInput.tabIndex = -1;
      this.importInput.setAttribute('aria-label', 'Choose presentation changes file');
      this.importInput.addEventListener('change', () => {
        var file = this.importInput.files && this.importInput.files[0];
        if (file) this.invoke('onImport', file);
        this.importInput.value = '';
      });
      this.importChangesButton = button('Import changes', 'pe-button pe-button-secondary', () => this.importInput.click());
      backupRow.append(this.importChangesButton);
      sharing.append(backupRow, this.importInput);
      sharing.append(element('p', 'pe-hint', this.studio ? 'Saved changes are available when you sign in on another device.' : 'Export a backup to continue editing on another browser.'));
      this.resetButton = button('Reset all edits', 'pe-button pe-button-link pe-reset', () => this.showResetDialog());
      sharing.append(this.resetButton);
      scrollArea.append(sharing);

      this.buildResetDialog();
      this.escapeListener = (event) => {
        if (event.key !== 'Escape') return;
        if (!this.resetOverlay.hidden) {
          event.preventDefault();
          event.stopPropagation();
          this.hideResetDialog();
        } else if (this.open) {
          event.preventDefault();
          event.stopPropagation();
          this.toggle(false);
        }
      };
      document.addEventListener('keydown', this.escapeListener, true);
      document.body.append(this.root);
      this.render({});
    }

    invoke(name, ...args) {
      var callback = this.callbacks[name];
      if (typeof callback === 'function') return callback(...args);
    }

    buildTextPanel() {
      var content = this.tabPanels.text;
      this.textInput = element('textarea', 'pe-input pe-text-input');
      this.textInput.id = this.idPrefix + '-text';
      this.textInput.rows = 6;
      this.textInput.spellcheck = true;
      content.append(field('Text', this.textInput, 'Edit the words, then apply. Existing typography is preserved.'));
      this.applyTextButton = button('Apply text', 'pe-button pe-button-primary pe-full', () => this.invoke('onApplyText', this.textInput.value));
      content.append(this.applyTextButton);
    }

    buildImagePanel() {
      var content = this.tabPanels.image;
      this.imageInput = element('input', 'pe-file-input');
      this.imageInput.type = 'file';
      this.imageInput.id = this.idPrefix + '-image';
      this.imageInput.accept = 'image/png,image/jpeg,image/webp,image/gif';
      this.imageInput.addEventListener('change', () => {
        this.pendingImage = this.imageInput.files && this.imageInput.files[0] || null;
        this.applyImageButton.textContent = this.pendingImage ? 'Replace image' : 'Apply image description';
      });
      content.append(field('Replace image', this.imageInput, 'PNG, JPEG, WebP, or GIF. Choose an image, then apply.'));
      this.altInput = element('textarea', 'pe-input');
      this.altInput.id = this.idPrefix + '-alt';
      this.altInput.rows = 3;
      content.append(field('Image description', this.altInput, 'Describe what the image shows for people using a screen reader.'));
      this.applyImageButton = button('Apply image description', 'pe-button pe-button-primary pe-full', () => this.invoke('onReplaceImage', this.pendingImage, this.altInput.value));
      content.append(this.applyImageButton);
    }

    buildMotionPanel() {
      var content = this.tabPanels.motion;
      this.motionLabel = element('p', 'pe-motion-label', 'Applies to this item');
      content.append(this.motionLabel);
      this.effectInput = element('select', 'pe-input');
      this.effectInput.id = this.idPrefix + '-effect';
      var effects = [
        ['original', 'Original motion'], ['none', 'No motion'], ['fade', 'Fade in'],
        ['up', 'Move up'], ['down', 'Move down'], ['left', 'Move left'],
        ['right', 'Move right'], ['zoom', 'Zoom in'], ['pop', 'Pop in']
      ];
      effects.forEach(([value, label]) => {
        var option = element('option', '', label);
        option.value = value;
        this.effectInput.append(option);
      });
      content.append(field('Entrance effect', this.effectInput));
      var timingRow = element('div', 'pe-timing-row');
      this.durationInput = element('input', 'pe-input');
      this.durationInput.id = this.idPrefix + '-duration';
      this.durationInput.type = 'number';
      this.durationInput.required = true;
      this.durationInput.min = '100';
      this.durationInput.max = '10000';
      this.durationInput.step = '50';
      this.durationInput.value = '600';
      this.delayInput = element('input', 'pe-input');
      this.delayInput.id = this.idPrefix + '-delay';
      this.delayInput.type = 'number';
      this.delayInput.required = true;
      this.delayInput.min = '0';
      this.delayInput.max = '10000';
      this.delayInput.step = '50';
      this.delayInput.value = '0';
      timingRow.append(field('Duration (ms)', this.durationInput), field('Delay (ms)', this.delayInput));
      content.append(timingRow);
      content.append(element('p', 'pe-hint', '1,000 ms = 1 second. Original motion restores the presentation’s existing animation.'));
      this.applyMotionButton = button('Apply motion', 'pe-button pe-button-primary pe-full', () => {
        if (!this.durationInput.reportValidity() || !this.delayInput.reportValidity()) return;
        this.invoke('onApplyMotion', {
          effect: this.effectInput.value,
          duration: Number(this.durationInput.value),
          delay: Number(this.delayInput.value)
        });
      });
      this.previewButton = button('Replay motion', 'pe-button pe-button-secondary pe-full', () => this.invoke('onPreview'));
      content.append(this.applyMotionButton, this.previewButton);
    }

    buildResetDialog() {
      this.resetOverlay = element('div', 'pe-dialog-overlay');
      this.resetOverlay.hidden = true;
      var dialog = element('div', 'pe-dialog');
      dialog.setAttribute('role', 'alertdialog');
      dialog.setAttribute('aria-modal', 'true');
      dialog.setAttribute('aria-labelledby', this.idPrefix + '-reset-title');
      dialog.setAttribute('aria-describedby', this.idPrefix + '-reset-description');
      var title = element('h3', 'pe-dialog-heading', 'Reset all edits?');
      title.id = this.idPrefix + '-reset-title';
      var description = element('p', 'pe-help', 'This restores the original text, images, and motion on every slide. Export your changes first if you want a backup.');
      description.id = this.idPrefix + '-reset-description';
      var actions = element('div', 'pe-dialog-actions');
      this.cancelResetButton = button('Keep editing', 'pe-button pe-button-secondary', () => this.hideResetDialog());
      this.confirmResetButton = button('Reset edits', 'pe-button pe-button-danger', () => {
        this.hideResetDialog();
        this.invoke('onReset');
      });
      actions.append(this.cancelResetButton, this.confirmResetButton);
      dialog.append(title, description, actions);
      this.resetOverlay.append(dialog);
      this.resetOverlay.addEventListener('click', (event) => {
        if (event.target === this.resetOverlay) this.hideResetDialog();
      });
      dialog.addEventListener('keydown', (event) => {
        if (event.key !== 'Tab') return;
        var atStart = document.activeElement === this.cancelResetButton;
        var atEnd = document.activeElement === this.confirmResetButton;
        if (event.shiftKey && atStart) {
          event.preventDefault();
          this.confirmResetButton.focus();
        } else if (!event.shiftKey && atEnd) {
          event.preventDefault();
          this.cancelResetButton.focus();
        }
      });
      this.root.append(this.resetOverlay);
    }

    showResetDialog() {
      this.resetOverlay.hidden = false;
      this.panel.inert = true;
      this.launcher.inert = true;
      this.cancelResetButton.focus();
    }

    hideResetDialog() {
      this.resetOverlay.hidden = true;
      this.panel.inert = false;
      this.launcher.inert = false;
      if (this.open) this.resetButton.focus();
    }

    toggle(open) {
      this.setOpen(open);
      this.invoke('onToggle', this.open);
    }

    setOpen(open) {
      var wasOpen = this.open;
      this.open = Boolean(open);
      this.root.classList.toggle('pe-is-open', this.open);
      this.panel.hidden = !this.open;
      this.launcher.hidden = this.open;
      this.launcher.setAttribute('aria-expanded', String(this.open));
      if (!this.open && !this.resetOverlay.hidden) this.hideResetDialog();
      if (this.open && !wasOpen) this.closeButton.focus({preventScroll: true});
      if (!this.open && wasOpen) this.launcher.focus({preventScroll: true});
    }

    activateTab(name, focus) {
      if (!this.tabButtons[name] || this.tabButtons[name].disabled) return;
      this.activeTab = name;
      Object.keys(this.tabButtons).forEach((key) => {
        var active = key === name;
        this.tabButtons[key].setAttribute('aria-selected', String(active));
        this.tabButtons[key].tabIndex = active ? 0 : -1;
        this.tabPanels[key].hidden = !active;
      });
      if (focus) this.tabButtons[name].focus();
    }

    navigateTabs(event, name) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      var enabled = Object.keys(this.tabButtons).filter((key) => !this.tabButtons[key].disabled);
      if (!enabled.length) return;
      event.preventDefault();
      var next = enabled.indexOf(name);
      if (event.key === 'Home') next = 0;
      else if (event.key === 'End') next = enabled.length - 1;
      else next = (next + (event.key === 'ArrowRight' ? 1 : -1) + enabled.length) % enabled.length;
      this.activateTab(enabled[next], true);
    }

    render(state) {
      this.state = Object.assign({}, this.state || {}, state || {});
      state = this.state;
      var selected = state.selected || null;
      var previousId = this.selected && this.selected.id;
      this.selected = selected;
      setText(this.slideLabel, state.slideLabel || 'Current slide');
      setText(this.selectionLabel, selected ? (selected.label || (selected.type === 'image' ? 'Image' : selected.type === 'motion' ? 'Motion group' : 'Text')) : 'No item selected');
      setText(this.status, state.status || 'Changes saved to this browser');
      this.root.classList.toggle('pe-status-error', state.statusKind === 'error' || Boolean(state.error));
      this.undoButton.disabled = !state.canUndo;
      this.redoButton.disabled = !state.canRedo;
      this.root.classList.toggle('pe-has-edits', Boolean(state.dirty));
      var blocked = state.loading === true;
      [this.applyTextButton, this.applyImageButton, this.applyMotionButton, this.downloadButton,
        this.exportChangesButton, this.importChangesButton, this.resetButton].forEach(control => { control.disabled = blocked; });
      this.saveOnlineButton.disabled = blocked || Boolean(state.saving) || !state.dirty;
      this.undoButton.disabled = blocked || !state.canUndo;
      this.redoButton.disabled = blocked || !state.canRedo;
      this.emptyState.hidden = Boolean(selected);
      this.tabs.hidden = !selected;
      this.tabButtons.text.disabled = !selected || selected.type !== 'text';
      this.tabButtons.image.disabled = !selected || selected.type !== 'image';
      this.tabButtons.motion.disabled = !selected;
      var items = Array.isArray(state.items) ? state.items : [];
      var itemsSignature = JSON.stringify(items.map((item) => [item.id, item.label, item.type]));
      if (itemsSignature !== this.lastItemsSignature) {
        this.itemsInput.replaceChildren();
        var placeholder = element('option', '', 'Select an item…');
        placeholder.value = '';
        this.itemsInput.append(placeholder);
        items.forEach((item) => {
          var label = item.label || (item.type === 'image' ? 'Image' : item.type === 'motion' ? 'Motion group' : 'Text');
          var option = element('option', '', label);
          option.value = item.id;
          this.itemsInput.append(option);
        });
        this.lastItemsSignature = itemsSignature;
      }
      this.itemsInput.disabled = !items.length;
      this.itemsInput.value = selected ? selected.id : '';

      if (!selected) {
        Object.values(this.tabPanels).forEach((panel) => { panel.hidden = true; });
        this.lastSelectionSignature = '';
        return;
      }

      var signature = JSON.stringify([selected.id, selected.type, selected.text, selected.alt, selected.motion]);
      setText(this.motionLabel, selected.motionLabel || 'Applies to this item');
      if (signature !== this.lastSelectionSignature) {
        this.textInput.value = selected.text || '';
        this.altInput.value = selected.alt || '';
        var motion = selected.motion || {};
        this.effectInput.value = motion.effect || 'original';
        if (!this.effectInput.value) this.effectInput.value = 'original';
        this.durationInput.value = Number.isFinite(motion.duration) ? motion.duration : 600;
        this.delayInput.value = Number.isFinite(motion.delay) ? motion.delay : 0;
        this.imageInput.value = '';
        this.pendingImage = null;
        this.applyImageButton.textContent = 'Apply image description';
        this.lastSelectionSignature = signature;
      }
      var nextTab = this.activeTab;
      if (selected.id !== previousId || this.tabButtons[nextTab].disabled) {
        nextTab = selected.type === 'text' ? 'text' : selected.type === 'image' ? 'image' : 'motion';
      }
      this.activateTab(nextTab, false);
    }

    destroy() {
      document.removeEventListener('keydown', this.escapeListener, true);
      this.root.remove();
    }
  }

  window.PresentationEditorUI = PresentationEditorUI;
})();

